const markMessagesRead = `-- name: MarkMessagesRead :exec
UPDATE support_messages SET read_at = $1
WHERE conversation_id = $2 AND read_at IS NULL AND sender = ANY($3::text[])
`

type MarkMessagesReadParams struct {
	Now            *time.Time
	ConversationID uuid.UUID
	Senders        []string
}

// The reader marks the other side's messages. 'agent' messages are read by the customer and
// vice versa; system messages count as the agent's.
func (q *Queries) MarkMessagesRead(ctx context.Context, arg MarkMessagesReadParams) error {
	_, err := q.db.Exec(ctx, markMessagesRead, arg.Now, arg.ConversationID, arg.Senders)
	return err
}

const nextCaseNumber = `-- name: NextCaseNumber :one
SELECT ('DSP-' || nextval('dispute_case_seq')::text)::text AS case_number
`

func (q *Queries) NextCaseNumber(ctx context.Context) (string, error) {
	row := q.db.QueryRow(ctx, nextCaseNumber)
	var case_number string
	err := row.Scan(&case_number)
	return case_number, err
}

const pickAgent = `-- name: PickAgent :one
SELECT s.id, s.name FROM staff s
WHERE s.disabled_at IS NULL AND 'support' = ANY(s.roles)
ORDER BY (SELECT count(*) FROM support_conversations c WHERE c.agent_id = s.id AND c.status <> 'resolved'), s.id
LIMIT 1
`

type PickAgentRow struct {
	ID   uuid.UUID
	Name string
}

// The enabled support agent with the fewest unresolved chats; ties go to the lowest ID, so the
// choice is the same on every call and tests are deterministic.
func (q *Queries) PickAgent(ctx context.Context) (PickAgentRow, error) {
	row := q.db.QueryRow(ctx, pickAgent)
	var i PickAgentRow
	err := row.Scan(&i.ID, &i.Name)
	return i, err
}

